INSERT INTO `principal_message` VALUES
(300010,'JENIFFER GACHAGO ',' PRINCIPAL - KIGUMO TECHNICAL  AND VOCATIONAL COLLEGE ','<p>On behalf of the Kigumo Technical and Vocational College Council, Management, and the entire KTVC fraternity, I welcome you to this institution.</p>\r\n\r\n<p>We are a TVETA-accredited public TVET institution located in Muthithi Town, Murang\'a County, committed to equipping learners with practical, industry-relevant skills for the 21st-century workforce.</p>\r\n\r\n<p>It is our pleasure to welcome you to Kigumo TVC under the leadership of the Principal, the chief executive of the institution. The office is responsible for overall coordination of academic and administrative functions, ensuring quality training, discipline, and achievement of the college’s mandate\r\n</p>\r\n\r\n<p>At Kigumo TVC, we believe in \"Skills for Self-Reliance.\" I invite you to explore our website and discover the opportunities awaiting you.</p>\r\n\r\n<p>Karibuni Sana!</p>\r\n\r\n','https://res.cloudinary.com/dabo8y2bw/image/upload/v1784810251/kigumo-tvc/principal/e3teng0inaf8f5w4ttlu.jpg',1,4,'2026-07-23 12:40:04'),
(330008,'JENIFFER GACHAGO ','Chief Principal - Kigumo Technical AND VOCATIONAL COLLEGE ','<p>On behalf of the Kigumo Technical and Vocational College Council, Management, and the entire KTVC fraternity, I welcome you to this institution.</p>\r\n\r\n<p>We are a TVETA-accredited public TVET institution located in Muthithi Town, Murang\'a County, committed to equipping learners with practical, industry-relevant skills for the 21st-century workforce.</p>\r\n\r\n<p>It is our pleasure to welcome you to Kigumo TVC under the leadership of the Principal, the chief executive of the institution. The office is responsible for overall coordination of academic and administrative functions, ensuring quality training, discipline, and achievement of the college’s mandate.</p>\r\n\r\n<p>At Kigumo TVC, we believe in \"Skills for Self-Reliance.\" I invite you to explore our website and discover the opportunities awaiting you.</p>\r\n\r\n<p>Karibuni Sana!</p>','https://res.cloudinary.com/dabo8y2bw/image/upload/v1784813575/kigumo-tvc/principal/kgyzdoungrckhmr0drwj.jpg',1,4,'2026-07-23 13:32:55');
